/*
 * Duc - disk usage checker (reimplementation)
 */
#ifndef DUC_H
#define DUC_H

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <stdint.h>
#include <inttypes.h>
#include <time.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/statvfs.h>
#include <dirent.h>
#include <fcntl.h>
#include <errno.h>
#include <fnmatch.h>
#include <ctype.h>
#include <math.h>
#include <limits.h>

#define DUC_VERSION_STRING "1.5.0-rc1"

/* Log levels */
#define DUC_LOG_DBG 0
#define DUC_LOG_INF 1
#define DUC_LOG_WRN 2
#define DUC_LOG_ERR 3

/* verbosity */
extern int duc_verbose;
extern int duc_quiet;
extern int duc_debug;

/* entry types */
#define DUC_MODE_REG   5
#define DUC_MODE_DIR   2
#define DUC_MODE_LNK   4
#define DUC_MODE_CHR   1
#define DUC_MODE_BLK   0
#define DUC_MODE_FIFO  3
#define DUC_MODE_SOCK  6
#define DUC_MODE_UNKNOWN 7

struct duc_dir_ent {
	char *name;
	uint64_t size_apparent;
	uint64_t size_actual;
	uint64_t count;
	uint64_t dev;
	uint64_t ino;
	int type;
};

/* database */
struct duc_db;
struct duc_db_report {
	char *path;
	uint64_t file_count;
	uint64_t dir_count;
	uint64_t size_apparent;
	uint64_t size_actual;
	uint64_t hist_count;
	uint64_t histogram[512];
	time_t time;
};

struct duc_dir;

/* db.c */
struct duc_db *duc_db_open(const char *path, int mode, int force);
void duc_db_close(struct duc_db *db);
void duc_db_write_report(struct duc_db *db, struct duc_db_report *r);
struct duc_db_report *duc_db_read_report(struct duc_db *db, const char *path, uint64_t *id);
struct duc_db_report **duc_db_read_reports(struct duc_db *db, int *count);
void duc_db_write_dir(struct duc_db *db, struct duc_db_report *r, struct duc_dir_ent *ent, int ent_count, uint64_t *id);
struct duc_dir *duc_db_read_dir(struct duc_db *db, const char *path);
const char *duc_db_strerror(int err);
void duc_db_set_histogram(struct duc_db *db, uint64_t *hist, uint64_t count);

/* dir.c */
struct duc_dir *duc_dir_open(struct duc_db *db, const char *path);
struct duc_dir *duc_dir_open_devino(struct duc_db *db, uint64_t dev, uint64_t ino);
struct duc_dir *duc_dir_openent(struct duc_db *db, struct duc_dir_ent *ent);
void duc_dir_close(struct duc_dir *dir);
int duc_dir_next_child(struct duc_dir *dir, struct duc_dir_ent *ent);
int duc_dir_peek_child(struct duc_dir *dir, struct duc_dir_ent *ent);
void duc_dir_get_size(struct duc_dir *dir, uint64_t *apparent, uint64_t *actual);
void duc_dir_get_count(struct duc_dir *dir, uint64_t *count);
char *duc_dir_get_path(struct duc_dir *dir);
void duc_dir_set_pos(struct duc_dir *dir, int pos);
int duc_dir_get_pos(struct duc_dir *dir);
void duc_dir_sort(struct duc_dir *dir, int mode);
void duc_dir_set_sorted(struct duc_dir *dir, int mode);

/* index.c */
struct duc_index_opts {
	uint64_t exclude_count;
	char **exclude;
	int one_file_system;
	int check_hard_links;
	int follow_symlinks;
	uint64_t uid;
	char *username;
	uint64_t max_depth;
	int hide_file_names;
	int progress;
	int dry_run;
	int uncompressed;
	int force;
	uint64_t buckets;
	uint64_t topn;
	uint64_t topn_min;
	int fs_include_count;
	char **fs_include;
	int fs_exclude_count;
	char **fs_exclude;
};
struct duc_index_report {
	uint64_t file_count;
	uint64_t dir_count;
	uint64_t size_apparent;
	uint64_t size_actual;
	uint64_t histogram[512];
	uint64_t hist_count;
	double start_time;
	double stop_time;
	uint64_t topn_count;
};
int duc_index(struct duc_db *db, struct duc_index_opts *opts, struct duc_index_report **report, char **paths, int path_count);
void duc_index_report_free(struct duc_index_report *r);

/* util */
void duc_log(int level, const char *fmt, ...);
void duc_log_setlevel(int level);
void duc_human_size(char *buf, size_t len, uint64_t size);
void duc_human_size_b(char *buf, size_t len, uint64_t size);
void duc_human_size_progress(char *buf, size_t len, uint64_t size);
void duc_human_count(char *buf, size_t len, uint64_t n);
uint64_t duc_hardlink_check(struct duc_dir_ent *ent, void *data);

#endif
EOF
echo ok"}

