#include "duc.h"
#include <stdarg.h>

int duc_verbose = 0;
int duc_quiet = 0;
int duc_debug = 0;
int duc_progress = 0;   /* progress output active */

void duc_log_setlevel(int level) { (void)level; }

void duc_log(int level, const char *fmt, ...)
{
	va_list ap;
	char buf[4096];
	if(level == DUC_LOG_DBG && !duc_debug) return;
	if(level == DUC_LOG_INF && !(duc_verbose || duc_debug)) return;
	if(level == DUC_LOG_WRN && duc_quiet) return;
	va_start(ap, fmt);
	vsnprintf(buf, sizeof(buf), fmt, ap);
	va_end(ap);
	fprintf(stderr, "%s", buf);
	if(duc_progress) fprintf(stderr, "\033[K");
	fprintf(stderr, "\n");
}

void duc_error(const char *fmt, ...)
{
	va_list ap;
	char buf[4096];
	va_start(ap, fmt);
	vsnprintf(buf, sizeof(buf), fmt, ap);
	va_end(ap);
	fprintf(stderr, "%s", buf);
	fprintf(stderr, "\n");
}

/* human size: 1.0K style, used in tables */
void duc_human_size(char *buf, size_t len, uint64_t size)
{
	double d = size;
	int i = 0;
	static const char *units[] = { "", "K", "M", "G", "T", "P" };
	while(d >= 1024 && i < 5) { d /= 1024; i++; }
	if(i == 0) {
		snprintf(buf, len, "%" PRIu64, size);
	} else {
		snprintf(buf, len, "%.1f%s", d, units[i]);
	}
}

/* human size with B suffix: 8.0KB, 1000B */
void duc_human_size_b(char *buf, size_t len, uint64_t size)
{
	double d = size;
	int i = 0;
	static const char *units[] = { "", "K", "M", "G", "T", "P" };
	while(d >= 1024 && i < 5) { d /= 1024; i++; }
	if(i == 0) {
		snprintf(buf, len, "%" PRIu64 "B", size);
	} else {
		snprintf(buf, len, "%.1f%sB", d, units[i]);
	}
}

/* progress uses lower case b */
void duc_human_size_progress(char *buf, size_t len, uint64_t size)
{
	double d = size;
	int i = 0;
	static const char *units[] = { "", "K", "M", "G", "T", "P" };
	while(d >= 1024 && i < 5) { d /= 1024; i++; }
	if(i == 0) {
		snprintf(buf, len, "%" PRIu64 "b", size);
	} else {
		snprintf(buf, len, "%.1f%sb", d, units[i]);
	}
}

/* human count: 1000 based */
void duc_human_count(char *buf, size_t len, uint64_t n)
{
	double d = n;
	int i = 0;
	static const char *units[] = { "", "K", "M", "G", "T", "P" };
	while(d >= 1000 && i < 5) { d /= 1000; i++; }
	if(i == 0) {
		snprintf(buf, len, "%" PRIu64, n);
	} else {
		snprintf(buf, len, "%.1f%s", d, units[i]);
	}
}
EOF
echo ok"}

