static void set_opt(struct opt_cmd *c, struct opt *o, char *value, int from_config)
{
	switch(o->type) {
	case OPT_FLAG:
		*(int *)o->val = 1;
		break;
	case OPT_INT:
		*(long *)o->val = value ? strtol(value, NULL, 10) : 0;
		break;
	case OPT_FLOAT:
		*(double *)o->val = value ? atof(value) : 0;
		break;
	case OPT_STRING: {
		char **arr = (char **)o->val;
		char *v = value ? strdup(value) : NULL;
		if(strcmp(o->l, "database") == 0) {
			db_path = v;
			db_set = from_config ? 1 : 2;
		} else {
			/* list option (exclude, fs-*) */
			arr = realloc(arr, sizeof(char *) * (list_count(arr)+1));
			arr[list_count(arr)] = v;
			arr[list_count(arr)] = NULL;
			*(char ***)o->val = arr;
		}
		break;
	}
	}
	o->set = from_config ? 1 : 2;
	(void)c;
}
