static void list_add(char ***list, int *count, char *val)
{
	*list = realloc(*list, sizeof(char *) * (*count + 2));
	(*list)[*count] = val;
	(*list)[(*count) + 1] = NULL;
	(*count)++;
}

static void apply_opt(struct opt_cmd *c, struct opt *o, char *value, int from_config)
{
	(void)c;
	switch(o->type) {
	case OPT_FLAG:
		*(int *)o->val = 1;
		break;
	case OPT_INT:
		*(long *)o->val = value ? strtol(value, NULL, 10) : 0;
		break;
	case OPT_FLOAT:
		*(double *)o->val = value ? atof(value) : 0;
		break;
	case OPT_STRING: {
		char *v = value ? strdup(value) : NULL;
		if(strcmp(o->l, "database") == 0) {
			db_raw = v;
			db_raw_set = from_config ? 1 : 2;
		} else if(strcmp(o->l, "exclude") == 0) {
			list_add(&o_exclude, &o_exclude_count, v);
		} else if(strcmp(o->l, "fs-include") == 0) {
			list_add(&o_fs_include, &o_fs_include_count, v);
		} else if(strcmp(o->l, "fs-exclude") == 0) {
			list_add(&o_fs_exclude, &o_fs_exclude_count, v);
		}
		break;
	}
	}
	o->set = from_config ? 1 : 2;
}

/* --- config file reading --- */
static void read_config_file(const char *path, struct opt_cmd *cmd)
{
	FILE *f = fopen(path, "r");
	if(!f) return;
	char line[4096];
	int section_ok = 1;   /* true if the current section applies */
	while(fgets(line, sizeof(line), f)) {
		/* strip comments and trailing newline */
		char *p = line;
		size_t n = strlen(p);
		while(n && (p[n-1] == '\n' || p[n-1] == '\r')) p[--n] = 0;
		/* trim */
		char *s = p;
		while(*s == ' ' || *s == '\t') s++;
		n = strlen(s);
		while(n && (s[n-1] == ' ' || s[n-1] == '\t')) s[--n] = 0;
		if(!*s) continue;
		if(*s == '#') continue;
		if(*s == '[') {
			char *e = strchr(s, ']');
			if(e) *e = 0;
			char *name = s + 1;
			section_ok = (strcmp(name, "global") == 0 || (cmd && strcmp(name, cmd->name) == 0));
			continue;
		}
		if(!section_ok) continue;
		/* split name / value */
		char *name = s;
		char *val = NULL;
		char *sp = strchr(s, ' ');
		if(!sp) sp = strchr(s, '\t');
		if(sp) {
			*sp = 0;
			val = sp + 1;
			while(*val == ' ' || *val == '\t') val++;
			n = strlen(val);
			while(n && (val[n-1] == ' ' || val[n-1] == '\t')) val[--n] = 0;
		}
		/* find option */
		struct opt *o = NULL;
		for(int k = 0; k < cmd->n; k++) {
			if(strcmp(cmd->opts[k].l, name) == 0) { o = &cmd->opts[k]; break; }
		}
		if(!o) {
			for(int k = 0; k < NGOPTS; k++) {
				if(strcmp(gopts[k].l, name) == 0) { o = &gopts[k]; break; }
			}
		}
		if(!o) {
			fprintf(stderr, "Unknown option '%s'\n", name);
			continue;
		}
		/* do not allow help/version from config */
		if(o == &gopts[1] || o == &gopts[4]) continue;
		if(val && !*val) val = NULL;
		apply_opt(cmd, o, val, 1);
	}
	fclose(f);
}

void duc_opt_read_config(struct opt_cmd *cmd)
{
	char buf[4096];
	const char *home = getenv("HOME");
	read_config_file("/etc/ducrc", cmd);
	if(home) {
		snprintf(buf, sizeof(buf), "%s/.config/duc/ducrc", home);
		read_config_file(buf, cmd);
		snprintf(buf, sizeof(buf), "%s/.ducrc", home);
		read_config_file(buf, cmd);
	}
	read_config_file("./.ducrc", cmd);
}

/* build getopt_long structure */
static struct option longopts[64];
static char shortbuf[128];

static void build_getopt(struct opt_cmd *cmd)
{
	int n = 0, m = 0;
	for(int k = 0; k < cmd->n; k++) {
		longopts[n].name = cmd->opts[k].l;
		longopts[n].has_arg = (cmd->opts[k].type == OPT_FLAG) ? no_argument : required_argument;
		longopts[n].flag = NULL;
		longopts[n].val = k;
		if(cmd->opts[k].s) {
			shortbuf[m++] = cmd->opts[k].s;
			if(cmd->opts[k].type != OPT_FLAG) shortbuf[m++] = ':';
		}
		n++;
	}
	for(int k = 0; k < NGOPTS; k++) {
		longopts[n].name = gopts[k].l;
		longopts[n].has_arg = no_argument;
		longopts[n].flag = NULL;
		longopts[n].val = 1000 + k;
		if(gopts[k].s) {
			shortbuf[m++] = gopts[k].s;
			if(gopts[k].type != OPT_FLAG) shortbuf[m++] = ':';
		}
		n++;
	}
	memset(&longopts[n], 0, sizeof(struct option));
	shortbuf[m] = 0;
}

int duc_opt_parse(struct opt_cmd *cmd, int argc, char **argv)
{
	duc_current_cmd = cmd;
	build_getopt(cmd);
	int idx;
	while(1) {
		int c = getopt_long(argc, argv, shortbuf, longopts, &idx);
		if(c == -1) break;
		if(c == '?') exit(1);
		if(c == ':') exit(1);
		if(c == 'h' || c == 1001) {
			duc_opt_print_help(cmd);
			exit(0);
		}
		if(c == 1004) { /* version */
			printf("%s", duc_version_text);
			exit(0);
		}
		if(c >= 1000) {
			apply_opt(cmd, &gopts[c-1000], NULL, 0);
			continue;
		}
		/* option value */
		char *val = optarg;
		if(cmd->opts[idx].type != OPT_FLAG && !val) val = NULL;
		apply_opt(cmd, &cmd->opts[idx], val, 0);
	}
	duc_verbose = g_verbose;
	duc_quiet = g_quiet;
	duc_debug = g_debug;
	return optind;
}

void duc_opt_print_help(struct opt_cmd *cmd)
{
	printf("%s%sGlobal options:\n%s%s", cmd->usage, cmd->opts, duc_global_options, cmd->tail);
}

void duc_opt_print_usage(struct opt_cmd *cmd)
{
	printf("%s", cmd->usage);
}

void duc_opt_print_main(void)
{
	printf("%s", duc_main_help);
}

/* resolve the database path */
void duc_opt_resolve_db(void)
{
	if(db_raw_set == 2) {
		o_database = db_raw;
		return;
	}
	if(db_raw_set == 1) {
		o_database = db_raw;
		if(o_database && !*o_database) {
			/* empty value from config leads to crash in original */
			volatile char *p = NULL;
			*p = 0;
		}
		return;
	}
	char *env = getenv("DUC_DATABASE");
	if(env && *env) {
		o_database = strdup(env);
		return;
	}
	const char *home = getenv("HOME");
	char buf[4096];
	snprintf(buf, sizeof(buf), "%s/.cache/duc/duc.db", home ? home : "");
	o_database = strdup(buf);
}
EOF
echo ok"}

