		if(val && !*val) val = NULL;
		apply_opt(cmd, o, val, 1);
	}
	fclose(f);
}

void duc_opt_read_config(struct opt_cmd *cmd)
{
	char buf[4096];
	const char *home = getenv("HOME");
	read_config_file("/etc/ducrc", cmd);
	if(home) {
		snprintf(buf, sizeof(buf), "%s/.config/duc/ducrc", home);
		read_config_file(buf, cmd);
		snprintf(buf, sizeof(buf), "%s/.ducrc", home);
		read_config_file(buf, cmd);
	}
	read_config_file("./.ducrc", cmd);
}

/* build getopt_long structure */
static struct option longopts[64];
static char shortbuf[128];

static void build_getopt(struct opt_cmd *cmd)
{
	int n = 0, m = 0;
	for(int k = 0; k < cmd->n; k++) {
		longopts[n].name = cmd->opts[k].l;
		longopts[n].has_arg = (cmd->opts[k].type == OPT_FLAG) ? no_argument : required_argument;
		longopts[n].flag = NULL;
		longopts[n].val = k;
		if(cmd->opts[k].s) {
			shortbuf[m++] = cmd->opts[k].s;
			if(cmd->opts[k].type != OPT_FLAG) shortbuf[m++] = ':';
		}
		n++;
	}
	for(int k = 0; k < NGOPTS; k++) {
		longopts[n].name = gopts[k].l;
		longopts[n].has_arg = no_argument;
		longopts[n].flag = NULL;
		longopts[n].val = 1000 + k;
		if(gopts[k].s) {
			shortbuf[m++] = gopts[k].s;
			if(gopts[k].type != OPT_FLAG) shortbuf[m++] = ':';
		}
		n++;
	}
	memset(&longopts[n], 0, sizeof(struct option));
	shortbuf[m] = 0;
}

int duc_opt_parse(struct opt_cmd *cmd, int argc, char **argv)
{
	duc_current_cmd = cmd;
	build_getopt(cmd);
	int idx;
	while(1) {
		int c = getopt_long(argc, argv, shortbuf, longopts, &idx);
		if(c == -1) break;
		if(c == '?') exit(1);
		if(c == ':') exit(1);
		if(c == 'h' || c == 1001) {
			duc_opt_print_help(cmd);
			exit(0);
		}
		if(c == 1004) { /* version */
			printf("%s", duc_version_text);
			exit(0);
		}
		if(c >= 1000) {
			apply_opt(cmd, &gopts[c-1000], NULL, 0);
			continue;
		}
		/* option value */
		char *val = optarg;
		if(cmd->opts[idx].type != OPT_FLAG && !val) val = NULL;
		apply_opt(cmd, &cmd->opts[idx], val, 0);
	}
	duc_verbose = g_verbose;
	duc_quiet = g_quiet;
	duc_debug = g_debug;
	return optind;
}

void duc_opt_print_help(struct opt_cmd *cmd)
{
	printf("%s%sGlobal options:\n%s%s", cmd->usage, cmd->opts, duc_global_options, cmd->tail);
}

void duc_opt_print_usage(struct opt_cmd *cmd)
{
	printf("%s", cmd->usage);
}

void duc_opt_print_main(void)
{
	printf("%s", duc_main_help);
}

/* resolve the database path */
void duc_opt_resolve_db(void)
{
	if(db_raw_set == 2) {
		o_database = db_raw;
		return;
	}
	if(db_raw_set == 1) {
		o_database = db_raw;
		if(o_database && !*o_database) {
			/* empty value from config leads to crash in original */
			volatile char *p = NULL;
			*p = 0;
		}
		return;
	}
	char *env = getenv("DUC_DATABASE");
	if(env && *env) {
		o_database = strdup(env);
		return;
	}
	const char *home = getenv("HOME");
	char buf[4096];
	snprintf(buf, sizeof(buf), "%s/.cache/duc/duc.db", home ? home : "");
	o_database = strdup(buf);
}
